scripts.build:lambda:
rm -rf dist-lambda lambda.zip && mkdir -p dist-lambda/dist dist-lambda/node_modules/.prisma && esbuild src/lambda.ts --bundle --platform=node --target=node20 --format=cjs --outfile=dist-lambda/dist/lambda.js --external:@prisma/client && printf '{
  "name": "lambda-runtime",
  "dependencies": {
    "@prisma/client": "7.10.0",
    "@prisma/adapter-pg": "^7.10.0",
    "pg": "^8.23.1"
  }
}
' > dist-lambda/package.json && cd dist-lambda && npm install --omit=dev && cp -r ../../node_modules/.pnpm/@prisma+client@*/node_modules/.prisma/client node_modules/.prisma/ && zip -q -r ../lambda.zip . -x '*.ts' '*.map'
